final class ShapeKit {
    private var builders: [String: () -> Shape] = [:]

    func register(_ key: String, _ make: @escaping () -> Shape) { builders[key] = make }

    func create(_ key: String) throws -> Shape {
        guard let make = builders[key] else { throw KitError.unknown(key, known: Array(builders.keys)) }
        return make()
    }
}
